      "content": "{\n  \"name\": \"dsh-chat-manager\",\n  \"version\": \"2.0.1\",\n  \"packageManager\": \"pnpm@11.19.0\",\n  \"description\": \"DeepSeek Harness archive content search and confirmed cleanup of unloaded local sessions\",\n  \"type\": \"module\",\n  \"main\": \"./src/index.js\",\n  \"icon\": \"./assets/icon.svg\",\n  \"exports\": {\n    \".\": \"./src/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\",\n    \"./locale/*\": \"./locale/*\"\n  },\n  \"files\": [\n    \"assets/icon.svg\",\n    \"locale/*.json\",\n    \"compatibility.json\",\n    \"cordis.patch.yml\",\n    \"lib/client.js\",\n    \"src/index.js\",\n    \"src/host/archive-manager.mjs\",\n    \"src/host/delete-session.mjs\",\n    \"src/host/plugin-request.mjs\",\n    \"README.md\",\n    \"README.en.md\",\n    \"README.zh-CN.md\",\n    \"AGENTS.md\",\n    \"LICENSE\",\n    \"SECURITY.md\",\n    \"THIRD_PARTY_NOTICES.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-workspace\",\n        \"@deepseek-ai/dsh-client-ui-primitives\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-session\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-context-menu\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"node scripts/build-client.mjs\",\n    \"test:behavior\": \"node --test tests/archive-manager-host.test.mjs tests/delete-session-client.test.mjs tests/delete-session-host.test.mjs tests/archive-settings.test.mjs tests/official-session-actions.test.mjs tests/smoke-ui.test.mjs\",\n    \"test:delivery\": \"node --test tests/accept-official-dsh.test.mjs tests/package-contract.test.mjs tests/prepare-compat-release.test.mjs\",\n    \"test\": \"node --test tests/*.test.mjs\",\n    \"check\": \"pnpm run test && pnpm run build && pnpm pack --pack-destination .artifacts\",\n    \"smoke:ui\": \"node scripts/smoke-ui.mjs\",\n    \"prepack\": \"node scripts/build-client.mjs\"\n  },\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"session\",\n    \"session-manager\",\n    \"session-management\",\n    \"conversation\",\n    \"archive\",\n    \"unarchive\",\n    \"restore\",\n    \"history-search\",\n    \"chat-history\",\n    \"conversation-history\",\n    \"archived-sessions\",\n    \"session-delete\",\n    \"permanent-delete\",\n    \"deepseek\",\n    \"delete\",\n    \"privacy\"\n  ],\n  \"author\": \"WSL043\",\n  \"license\": \"MIT\",\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"tag\": \"latest\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/WSL043/dsh-chat-manager.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/WSL043/dsh-chat-manager/issues\"\n  },\n  \"homepage\": \"https://github.com/WSL043/dsh-chat-manager#readme\",\n  \"engines\": {\n    \"node\": \">=24.9.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.1.0\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-session\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-workspace\": \"0.2.2-rc.1\",\n    \"react\": \"^18.2.0\",\n    \"@deepseek-ai/dsh-client-ui-context-menu\": \"0.2.2-rc.1\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-primitives\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-session\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-workspace\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-context-menu\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.1.0\",\n    \"playwright\": \"1.63.0\"\n  }\n}\n"
