      "path": "tests/archive-manager-host.test.mjs",
      "content": "import assert from 'node:assert/strict'\nimport { Readable } from 'node:stream'\nimport test from 'node:test'\n\nimport {\n  createArchiveRequestHandlers,\n  reconcileDeletedArchive,\n  restoreArchivedSession,\n  searchArchivedSessions,\n} from '../src/host/archive-manager.mjs'\nimport { hostRequestFence, sameOriginRequest } from '../src/host/delete-session.mjs'\nimport { currentConnection } from '../src/index.js'\n\nconst A = 'session-archive-a'\nconst B = 'session-archive-b'\nconst fixtureConnection = { requestRejection: req => !sameOriginRequest(req) ? 403\n  : req.headers.cookie === 'fixture-auth' ? undefined : 401 }\nconst fixtureFence = hostRequestFence(fixtureConnection)\n\nconst deleteSessionAndReconcileArchive = async ({ deleteSession, ...options }, id) =>\n  reconcileDeletedArchive(options, id, await deleteSession(id))\n\ntest('verified absent transcript clears only its stale archive marker', async () => {\n  const workspaceRegistry = registry()\n  const result = await deleteSessionAndReconcileArchive({ workspaceRegistry,\n    deleteSession: async () => ({ ok: true, value: { deleted: false, alreadyAbsent: true } }),\n  }, A)\n  assert.deepEqual(result, { ok: true, value: { deleted: false, alreadyAbsent: true, archiveReconciled: true } })\n  assert.deepEqual(workspaceRegistry.archivedSessionIds, [B])\n})\n\ntest('failed stale-marker reconciliation is not reported as deletion success', async () => {\n  const result = await deleteSessionAndReconcileArchive({\n    workspaceRegistry: { archivedSessionIds: [A], unarchiveSession: async () => { throw Error('write failed') } },\n    deleteSession: async () => ({ ok: true, value: { deleted: false, alreadyAbsent: true } }), warn() {},\n  }, A)\n  assert.equal(result.ok, false)\n  assert.equal(result.error.code, 'archive-reconcile-failed')\n})\n\ntest('public unarchive API owns restoration without private registry access', async () => {\n  const workspaceRegistry = {\n    archivedSessionIds: [A, B],\n    async unarchiveSession(id) { this.archivedSessionIds = this.archivedSessionIds.filter(value => value !== id) },\n    requireState() { throw new Error('private registry must not be read') },\n  }\n  assert.deepEqual(await restoreArchivedSession(workspaceRegistry, A), { restored: true, archivedSessionIds: [B] })\n  assert.deepEqual(await restoreArchivedSession(workspaceRegistry, A), { restored: false, archivedSessionIds: [B] })\n})\n\ntest('public unarchive rejection never falls back to private writes', async () => {\n  let fallbackCalled = false\n  const workspaceRegistry = {\n    archivedSessionIds: [A],\n    async unarchiveSession() { throw new Error('storage unavailable') },\n    enqueueOperation() { fallbackCalled = true },\n    requireState() {}, setState() {},\n  }\n  await assert.rejects(restoreArchivedSession(workspaceRegistry, A), /storage unavailable/)\n  assert.equal(fallbackCalled, false)\n  assert.deepEqual(workspaceRegistry.archivedSessionIds, [A])\n})\n\nfunction registry(ids = [A, B]) {\n  let state = { initialized: true, workspaceIds: ['workspace-a'], archivedSessionIds: [...ids] }\n  return {\n    get archivedSessionIds() {\n      return state.archivedSessionIds\n    },\n    unarchiveSession: async id => { state = { ...state, archivedSessionIds: state.archivedSessionIds.filter(value => value !== id) } },\n    snapshot: () => state,\n  }\n}\n\ntest('restores exactly one archived session while preserving registry order', async () => {\n  const workspaceRegistry = registry()\n\n  const result = await restoreArchivedSession(workspaceRegistry, A)\n\n  assert.deepEqual(result, { restored: true, archivedSessionIds: [B] })\n  assert.deepEqual(workspaceRegistry.snapshot(), {\n    initialized: true,\n    workspaceIds: ['workspace-a'],\n    archivedSessionIds: [B],\n  })\n})\n\ntest('restoring an active session is an idempotent no-op', async () => {\n  const workspaceRegistry = registry([B])\n\n  const result = await restoreArchivedSession(workspaceRegistry, A)\n\n  assert.deepEqual(result, { restored: false, archivedSessionIds: [B] })\n  assert.deepEqual(workspaceRegistry.snapshot().archivedSessionIds, [B])\n})\n\ntest('restore fails closed when the tested workspace registry seam drifts', async () => {\n  await assert.rejects(\n    restoreArchivedSession({ archivedSessionIds: [A] }, A),\n    /public workspace unarchive API is unavailable/,\n  )\n})\n\ntest('searches only archived current user and assistant history with a bounded result page', async () => {\n  const calls = []\n  const signal = AbortSignal.timeout(5_000)\n  const workspaceRegistry = registry()\n  const sessionQuery = {\n    searchSessions: async (request, exec) => {\n      calls.push({ request, exec })\n      return {\n        items: [\n          {\n            header: { id: A },\n            bestMatch: {\n              sessionId: A,\n              type: 'assistant/message',\n              surface: 'current',\n              snippet: 'the archived answer',\n            },\n          },\n          {\n            header: { id: 'not-archived' },\n            bestMatch: {\n              sessionId: 'not-archived',\n              type: 'user/message',\n              surface: 'current',\n              snippet: 'must not escape the archive filter',\n            },\n          },\n        ],\n        nextCursor: 'more-results',\n      }\n    },\n  }\n\n  const result = await searchArchivedSessions({ workspaceRegistry, sessionQuery }, '  archived  ', signal)\n\n  assert.deepEqual(result, {\n    items: [{ sessionId: A, snippet: 'the archived answer' }],\n    hasMore: true,\n  })\n  assert.deepEqual(calls[0].request, {\n    query: 'archived',\n    sessionFilters: [{ kind: 'id', values: [A, B] }],\n    eventFilters: [\n      { kind: 'type', values: ['user/message', 'assistant/message'] },\n      { kind: 'surface', values: ['current'] },\n    ],\n    limit: 20,\n  })\n  assert.equal(calls[0].exec.signal, signal)\n})\n\ntest('archived search returns no results without invoking the provider when the archive is empty', async () => {\n  let called = false\n  const result = await searchArchivedSessions({\n    workspaceRegistry: registry([]),\n    sessionQuery: { searchSessions: async () => { called = true } },\n  }, 'needle', new AbortController().signal)\n\n  assert.deepEqual(result, { items: [], hasMore: false })\n  assert.equal(called, false)\n})\n\ntest('falls back to DSH event filtering when the optional full-text index is disabled', async () => {\n  const workspaceRegistry = registry([A, B])\n  const calls = []\n  const sessionQuery = {\n    async searchSessions() {\n      const error = new Error('search disabled')\n      error.code = 'SESSION_QUERY_SEARCH_DISABLED'\n      throw error\n    },\n    async filterEvents(sessionId, filters) {\n      calls.push({ sessionId, filters })\n      return sessionId === A\n        ? [{ sessionId: A, type: 'assistant/message', surface: 'current', text: 'A useful archived implementation detail' }]\n        : []\n    },\n  }\n\n  const result = await searchArchivedSessions({ workspaceRegistry, sessionQuery }, 'implementation')\n\n  assert.deepEqual(result, {\n    items: [{ sessionId: A, snippet: 'A useful archived implementation detail' }],\n    hasMore: false,\n  })\n  assert.equal(calls.length, 2)\n  assert.deepEqual(calls[0].filters, [\n    { kind: 'type', values: ['user/message', 'assistant/message'] },\n    { kind: 'surface', values: ['current'] },\n    { kind: 'text', text: 'implementation' },\n  ])\n})\n\ntest('archived search rejects empty, oversized, and NUL-bearing queries', async () => {\n  const deps = { workspaceRegistry: registry(), sessionQuery: { searchSessions: async () => ({ items: [] }) } }\n  const signal = new AbortController().signal\n\n  await assert.rejects(searchArchivedSessions(deps, '   ', signal), /invalid archive search query/)\n  await assert.rejects(searchArchivedSessions(deps, 'x'.repeat(501), signal), /invalid archive search query/)\n  await assert.rejects(searchArchivedSessions(deps, 'bad\\0query', signal), /invalid archive search query/)\n})\n\ntest('archive HTTP search does not reply after a provider ignores request cancellation', async () => {\n  let observedSignal\n  let completeSearch\n  const handlers = createArchiveRequestHandlers({\n    isTrustedRequest: fixtureFence,\n    restore: async () => {},\n    search: async (_query, signal) => {\n      observedSignal = signal\n      await new Promise(resolvePromise => { completeSearch = resolvePromise })\n      return { items: [], hasMore: false }\n    },\n    warn: () => {},\n  })\n  const req = request(JSON.stringify({ query: 'needle' }))\n  const res = response()\n  const pending = handlers.search(req, res)\n  await new Promise(resolvePromise => setImmediate(resolvePromise))\n  req.emit('aborted')\n  completeSearch()\n  await pending\n\n  assert.equal(observedSignal.aborted, true)\n  assert.equal(res.status, undefined)\n})\n\ntest('archive fallback rejects cancellation during its final batch', async () => {\n  const controller = new AbortController()\n  const calls = []\n  let completeBatch\n  const batchReady = new Promise(resolvePromise => { completeBatch = resolvePromise })\n  const sessionQuery = {\n    async searchSessions() {\n      const error = new Error('search disabled')\n      error.code = 'SESSION_QUERY_SEARCH_DISABLED'\n      throw error\n    },\n    async filterEvents(sessionId) {\n      calls.push(sessionId)\n      await batchReady\n      return []\n    },\n  }\n\n  const pending = searchArchivedSessions({\n    workspaceRegistry: registry([A, B, 'session-archive-c', 'session-archive-d']),\n    sessionQuery,\n  }, 'needle', controller.signal)\n  await new Promise(resolvePromise => setImmediate(resolvePromise))\n  controller.abort()\n  completeBatch()\n  await assert.rejects(pending)\n\n  assert.deepEqual(calls, [A, B, 'session-archive-c', 'session-archive-d'])\n})\n\ntest('permanent deletion removes a stale archive marker only after storage deletion succeeds', async () => {\n  const workspaceRegistry = registry()\n  const result = await deleteSessionAndReconcileArchive({\n    workspaceRegistry,\n    deleteSession: async () => ({ ok: true, value: { deleted: true } }),\n  }, A)\n\n  assert.deepEqual(result, { ok: true, value: { deleted: true, archiveReconciled: true } })\n  assert.deepEqual(workspaceRegistry.snapshot().archivedSessionIds, [B])\n\n  const untouched = registry()\n  const refused = await deleteSessionAndReconcileArchive({\n    workspaceRegistry: untouched,\n    deleteSession: async () => ({ ok: false, error: { code: 'storage-error', message: 'refused' } }),\n  }, A)\n  assert.deepEqual(refused, { ok: false, error: { code: 'storage-error', message: 'refused' } })\n  assert.deepEqual(untouched.snapshot().archivedSessionIds, [A, B])\n})\n\nfunction request(body, headers = {}) {\n  const stream = Readable.from([body])\n  stream.method = 'POST'\n  stream.headers = {\n    host: '127.0.0.1:14171',\n    origin: 'http://127.0.0.1:14171',\n    cookie: 'fixture-auth',\n    'content-type': 'application/json',\n    ...headers,\n  }\n  return stream\n}\n\nfunction response() {\n  return {\n    status: undefined,\n    headers: undefined,\n    body: '',\n    writeHead(status, headers) {\n      this.status = status\n      this.headers = headers\n    },\n    end(body = '') {\n      this.body += body\n    },\n  }\n}\n\ntest('archive HTTP search accepts only same-origin JSON and exposes no duplicate restore route', async () => {\n  const calls = []\n  const handlers = createArchiveRequestHandlers({ isTrustedRequest: fixtureFence, search: async query => { calls.push(query); return { items: [], hasMore: false } } })\n  assert.equal(handlers.restore, undefined)\n  const searched = response()\n  await handlers.search(request(JSON.stringify({ query: 'needle' })), searched)\n  assert.equal(searched.status, 200)\n  assert.deepEqual(calls, ['needle'])\n  const crossOrigin = response()\n  await handlers.search(request(JSON.stringify({ query: 'needle' }), { origin: 'https://attacker.example' }), crossOrigin)\n  assert.equal(crossOrigin.status, 403)\n  assert.equal(calls.length, 1)\n})\n\ntest('archive search refuses absent Host admission and preserves late-ready authentication rejections', async () => {\n  let calls = 0, connection\n  const search = async () => { calls++; return { items: [], hasMore: false } }\n  for (const isTrustedRequest of [undefined, hostRequestFence(undefined), hostRequestFence({})]) {\n    const handlers = createArchiveRequestHandlers({ search, isTrustedRequest })\n    const res = response()\n    await handlers.search(request(JSON.stringify({ query: 'needle' })), res)\n    assert.equal(res.status, 403)\n    assert.equal(calls, 0)\n  }\n  const ctx = { get: () => connection }\n  const handlers = createArchiveRequestHandlers({ search,\n    isTrustedRequest: req => hostRequestFence(currentConnection(ctx))(req),\n  })\n  const beforeReady = response()\n  await handlers.search(request(JSON.stringify({ query: 'needle' })), beforeReady)\n  assert.equal(beforeReady.status, 403)\n  connection = fixtureConnection\n  for (const [headers, status] of [[{ cookie: undefined }, 401], [{ origin: 'https://attacker.example' }, 403], [{}, 200]]) {\n    const res = response()\n    await handlers.search(request(JSON.stringify({ query: 'needle' }), headers), res)\n    assert.equal(res.status, status)\n  }\n  assert.equal(calls, 1)\n})\n\ntest('archive HTTP search rejects malformed queries without calling the provider', async () => {\n  let calls = 0\n  const handlers = createArchiveRequestHandlers({ isTrustedRequest: fixtureFence, search: async () => { calls++ } })\n  for (const body of ['{', JSON.stringify({ query: '   ' })]) {\n    const res = response(); await handlers.search(request(body), res)\n    assert.equal(res.status, 400)\n  }\n  assert.equal(calls, 0)\n})\n\ntest('archive search cancels bounded fallback work when the browser abandons the request', async () => {\n  let observedSignal\n  const handlers = createArchiveRequestHandlers({\n    isTrustedRequest: fixtureFence,\n    restore: async () => {},\n    search: async (_query, signal) => {\n      observedSignal = signal\n      await new Promise((resolvePromise, reject) => {\n        signal.addEventListener('abort', () => reject(signal.reason), { once: true })\n      })\n    },\n    warn: () => {},\n  })\n  const req = request(JSON.stringify({ query: 'needle' }))\n  const res = response()\n  const pending = handlers.search(req, res)\n  await new Promise(resolvePromise => setImmediate(resolvePromise))\n  req.emit('aborted')\n  await pending\n\n  assert.equal(observedSignal.aborted, true)\n  assert.equal(res.status, undefined)\n})\n\ntest('archive ID pushdown finds archives beyond a full page of active matches', async () => {\n  const corpus = [...Array.from({ length: 25 }, (_, index) => 'active-' + index), A]\n  const result = await searchArchivedSessions({ workspaceRegistry: registry([A]), sessionQuery: {\n    searchSessions: async request => {\n      const allowed = request.sessionFilters?.find(filter => filter.kind === 'id')?.values\n      const visible = corpus.filter(id => !allowed || allowed.includes(id))\n      return { items: visible.slice(0, request.limit).map(id => ({ header: { id }, bestMatch: { sessionId: id, type: 'assistant/message', surface: 'current', snippet: 'needle' } })) }\n    },\n  } }, 'needle')\n  assert.deepEqual(result.items, [{ sessionId: A, snippet: 'needle' }])\n})\n\ntest('index-disabled fallback uses at most four concurrent scans and bounds results', async () => {\n  let concurrent = 0, maximum = 0, calls = 0\n  const result = await searchArchivedSessions({ workspaceRegistry: registry(Array.from({ length: 40 }, (_, i) => 'archive-' + i)), sessionQuery: {\n    searchSessions: async () => { throw Object.assign(Error('disabled'), { code: 'SESSION_QUERY_SEARCH_DISABLED' }) },\n    filterEvents: async id => { calls++; concurrent++; maximum = Math.max(maximum, concurrent); await Promise.resolve(); concurrent--\n      return [{ sessionId: id, type: 'user/message', surface: 'current', text: 'needle' }] },\n  } }, 'needle')\n  assert.equal(maximum, 4); assert.equal(calls, 24)\n  assert.equal(result.items.length, 20); assert.equal(result.hasMore, true)\n})\n"
    },
